package com.indianservers.krishna4u.feature.teachings

import androidx.annotation.DrawableRes
import com.indianservers.krishna4u.R

data class TeachingUi(
    val id: String,
    val title: String,
    val summary: String,
    val category: String,
    val source: String,
    val question: String,
    val teaching: String,
    val takeaways: List<String>,
    val practice: String,
    @DrawableRes val icon: Int
)

private fun compassion(
    id: String, title: String, summary: String, question: String, teaching: String,
    takeaways: List<String>, practice: String, @DrawableRes icon: Int = R.drawable.icon_compassion
) = TeachingUi(id, title, summary, "Compassion", "Book Chapter 3", question, teaching, takeaways, practice, icon)

private fun gita(
    chapter: Int, title: String, summary: String, question: String, teaching: String,
    takeaways: List<String>, practice: String, @DrawableRes icon: Int = R.drawable.icon_teachings
) = TeachingUi("gita-path-$chapter", title, summary, "Gita Wisdom", "Book Chapter 4 · Gita Chapter $chapter", question, teaching, takeaways, practice, icon)

private fun dharma(
    id: String, title: String, summary: String, question: String, teaching: String,
    takeaways: List<String>, practice: String, @DrawableRes icon: Int = R.drawable.icon_dharma
) = TeachingUi(id, title, summary, "Daily Dharma", "Book Chapter 5", question, teaching, takeaways, practice, icon)

